'use strict';
const $=id=>document.getElementById(id),C=HALCore,A=HALAnalytics;
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(n,d=2)=>C.finite(n)?n.toLocaleString('en-IN',{maximumFractionDigits:d}):'—';
const money=n=>C.finite(n)?(n<0?'−':'')+'₹'+Math.abs(n).toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2}):'₹—';
const signed=n=>C.finite(n)?(n>=0?'+':'−')+fmt(Math.abs(n)):'—';
const when=s=>s&&Number.isFinite(Date.parse(s))?new Date(s).toLocaleString('en-IN',{timeZone:'Asia/Kolkata',day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit',hour12:false})+' IST':'Time unavailable';
const dateText=s=>A.expiryTime(s)?new Date(s+'T00:00:00Z').toLocaleDateString('en-IN',{timeZone:'UTC',day:'2-digit',month:'short',year:'numeric'}):String(s||'—');
const shortDate=s=>C.validDate(s)?new Date(s+'T00:00:00Z').toLocaleDateString('en-IN',{timeZone:'UTC',day:'2-digit',month:'short'}):'—';
const dataRow=(label,value)=>`<div class="data-row"><span>${esc(label)}</span><b>${esc(value)}</b></div>`;
const tile=(label,value,note='')=>`<div class="metric-tile"><small>${esc(label)}</small><b>${esc(value)}</b><span>${esc(note)}</span></div>`;
const empty=text=>`<div class="empty">${esc(text)}</div>`;
const blank=type=>({type:type||'PE',expiry:'',lots:'',lotSize:'',entry:'',strike:'',manual:''});
let book=A.emptyBook(),snapshot=null,research={},history=[],draft=[],tab='overview',frame='D',chainMode='puts',newsFilter='all',configured=false,mode='direct',started=false,loading=false,lastFailed=false,actionSave=null;
const pending=new Map(),failed=new Map(),researchStarted=new Map();let visit=null,allNews=[];
const issues={credential_missing:'Add your Upstox token in Connection.',token_missing:'Your Render server needs UPSTOX_ACCESS_TOKEN. You can also use Direct Upstox on this phone.',token_expired_or_unauthorized:'Upstox rejected the token. Replace it in Connection. An Analytics Token is recommended for read-only research.',viewer_unauthorized:'The Render viewer key is missing or incorrect. Check HAL_VIEWER_KEY or use Direct Upstox.',upstox_permission_denied:'This token cannot access the requested feed. Check its Upstox permissions.',upstox_rate_limited:'Rate limit reached. Wait a minute before refreshing.',network_unavailable:'Could not reach the data source. Check your connection and retry.',server_unavailable:'Render is unavailable, starting up, or needs the research update. Try Direct Upstox.',no_hal_equity_instrument:'The exact NSE HAL instrument was not available.',no_hal_option_contracts:'Active HAL option contracts were unavailable.',no_hal_spot_quote:'A valid HAL spot quote was unavailable.',expiry_not_listed:'This expiry is no longer listed. Review your saved contracts.',invalid_expiry:'Choose a valid expiry.',refresh_too_soon:'Wait a few seconds before refreshing again.',connection_changed:'Connection changed. Refresh once the previous request finishes.',secure_storage_unavailable:'Unlock your phone and re-enter the credential in Connection.',bad_response:'Unexpected provider response. Previous data is retained.',upstox_request_failed:'This Upstox feed is unavailable. Check token access and retry.',redirect_blocked:'The source redirected its request. The connection was stopped.',official_feed_unavailable:'The official feed is temporarily unavailable.'};
function toast(text){$('toast').textContent=text;$('toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').classList.remove('visible'),4500);}
function notice(text,type=''){const n=$('notice');n.textContent=text;n.className='notice '+type+(text?'':' hidden');}
function native(action,arg){if(window.HALNative&&typeof HALNative[action]==='function'){arg===undefined?HALNative[action]():HALNative[action](arg);}else toast('Install the Android APK to connect or manage files securely.');}
function color(el,n){el.classList.remove('positive','negative');if(C.finite(n))el.classList.add(n<0?'negative':'positive');}
function saveBook(next){const clean=A.validateBook(next);localStorage.setItem('hal_desk_v2',JSON.stringify(clean));book=clean;invalidateAIForBook();return clean;}
function saveCache(){try{localStorage.setItem('hal_cache_v2',JSON.stringify({snapshot,research,history:history.slice(-5000)}));}catch(e){toast('Local cache is full. Your saved open book is separate; export a backup.');}}
function effectiveSnapshot(){
 const dates=[...new Set(book.legs.filter(l=>l.type==='PE').map(l=>l.expiry))];
 const state=HALDesk.valuation(snapshot,Object.fromEntries(dates.map(d=>[d,getResearch('hedges',d)?.data])),book.legs,{lastFailed,failed:dates.filter(d=>failed.has(key('chain',d))||failed.has(key('hedges',d))),pending:dates.filter(d=>pending.has(key('chain',d))||pending.has(key('hedges',d)))});
 return state?{...state,markMode:book.preferences.markMode}:null;
}
function key(section,f=frame,type=$('statement-type').value){return section+':'+f+':'+(section==='fundamentals'?type:'consolidated');}
function getResearch(section,f='D'){return research[key(section,f)];}
function requestResearch(section,f='D',force=false){if(!configured&&section!=='filings')return;const k=key(section,f),cached=research[k],ttl=section==='hedges'?30000:section==='fundamentals'?21600000:section==='candles'?900000:section==='chain'||section==='status'||section==='context'?60000:900000;if(pending.has(k)||(!force&&cached&&Date.now()-Date.parse(cached.fetched_at_iso)<ttl))return;if(section==='hedges'&&Date.now()-(researchStarted.get(k)||0)<15000){if(force)toast('Held quotes were just requested. Wait 15 seconds before retrying.');return;}researchStarted.set(k,Date.now());pending.set(k,Date.now());failed.delete(k);native('research',JSON.stringify({section,frame:f,type:section==='fundamentals'?$('statement-type').value:'consolidated'}));renderHealth();renderDesk();if(section==='hedges')renderPositions();}
function primeResearch(){requestResearch('candles','D');requestResearch('news');requestResearch('fundamentals');requestResearch('filings');requestResearch('status');requestResearch('context');refreshHeldQuotes();}
function refreshHeldQuotes(force=false){
 if(!configured||!snapshot)return;
 for(const d of [...new Set(book.legs.filter(l=>l.type==='PE'&&A.daysLeft(l.expiry)>=0).map(l=>l.expiry))])requestResearch('hedges',d,force);
}
function refresh(){if(loading)return;if(!configured){native('settings');return;}native('refresh',$('expiry').value||'');}
function switchTab(next){tab=next;const parent=['markets','news','insights','ai'].includes(next)?'research':next;$('desk-research-nav').classList.toggle('hidden',parent!=='research');document.querySelectorAll('#desk-research-nav button').forEach(b=>b.classList.toggle('selected',b.dataset.go===next));if(next==='ai')loadAIConfig();document.querySelectorAll('.view').forEach(v=>v.classList.toggle('active',v.id==='view-'+next));document.querySelectorAll('.bottom-nav button').forEach(b=>{b.classList.toggle('selected',b.dataset.tab===parent);b.setAttribute('aria-current',b.dataset.tab===parent?'page':'false');});window.scrollTo(0,0);if(next==='markets'||next==='research'){requestResearch('candles',frame);setTimeout(renderCharts,30);}if(next==='news'){requestResearch('news');requestResearch('filings');HALNewsAI.maybeScore(allNews);}if(next==='research')requestResearch('fundamentals');if(next==='overview')setTimeout(renderCharts,30);}
function panel(prefix,name){document.querySelectorAll('#'+prefix+'-tabs button').forEach(b=>b.classList.toggle('selected',b.dataset.panel===name));document.querySelectorAll('[id^="'+prefix+'-"]').forEach(el=>{if(el.classList.contains('subpanel'))el.classList.toggle('active',el.id===prefix+'-'+name);});}
function applyTheme(){const theme=book.preferences.theme,light=theme==='light'||(theme==='system'&&matchMedia('(prefers-color-scheme: light)').matches);document.documentElement.dataset.theme=light?'light':'dark';document.querySelector('meta[name=theme-color]').content=light?'#ffffff':'#0c0f11';renderCharts();}
function researchStatus(section,f='D'){const k=key(section,f),r=research[k];if(pending.has(k))return 'Refreshing '+section+'…';if(failed.has(k))return (issues[failed.get(k)]||'Feed unavailable.')+(r?' Previous copy: '+when(r.fetched_at_iso):'');if(!r)return configured?'Waiting for '+section+' data.':'Connect Upstox to load '+section+'.';return r.source+' · Retrieved '+when(r.fetched_at_iso)+(Object.keys(r.errors||{}).length?' · Some fields unavailable':'');}
function rawCandles(f=frame){const d=getResearch('candles',f)?.data;return [...(d?.history?.candles||[]),...(d?.intraday?.candles||[])];}
function technical(f=frame){const r=getResearch('candles',f);return A.technicals(rawCandles(f),f,Date.now(),failed.has(key('candles',f))?null:r?.fetched_at_iso);}
function renderCharts(){try{const d=A.candles(rawCandles('D'));HALCharts.draw('overview-chart',d.slice(-60),'D',true);const rows=A.candles(rawCandles());const levels=book.legs.map(l=>({price:l.type==='PE'?l.strike:l.entry,title:l.type==='PE'?fmt(l.strike,0)+' put':'FUT entry'}));HALCharts.draw('market-chart',rows,frame,false,levels);$('candle-status').textContent=researchStatus('candles',frame)+' · Bars use IST.';}catch(e){$('candle-status').textContent='Chart unavailable. Research figures remain available.';}}
function renderMarket(){const s=snapshot?.spot||{};$('spot').textContent=money(s.last_price);const change=C.finite(s.last_price)&&s.prev_close>0?s.last_price-s.prev_close:null;$('change').textContent=C.finite(change)?signed(change)+' ('+signed(change/s.prev_close*100)+'%) vs previous close':'Your market. Your perspective.';color($('change'),change);$('quote-age').textContent=snapshot?(lastFailed?'Previous snapshot · ':'Quote · ')+when(s.quote_as_of):'Awaiting market data';$('welcome').classList.toggle('hidden',!!snapshot);const st=getResearch('status')?.data?.market?.status;$('market-status').textContent=st?'NSE · '+st.replaceAll('_',' '):'NSE · STATUS UNKNOWN';$('market-ohlc').innerHTML=[['OPEN',s.open],['HIGH',s.high],['LOW',s.low],['PREV. CLOSE',s.prev_close]].map(([l,v])=>`<div><small>${l}</small><b>${fmt(v)}</b></div>`).join('');
 $('futures').innerHTML=(snapshot?.futures||[]).map((c,i)=>`<article class="future-card"><div class="future-top"><div><small>${i===0?'NEAR CONTRACT':'FUTURES'}</small><strong>${esc(dateText(c.expiry))}</strong></div><span class="price">${money(c.quote?.last_price)}</span></div><div class="stats"><div><small>LOT SIZE</small><b>${fmt(c.lot_size,0)} units</b></div><div><small>OPEN INTEREST</small><b>${fmt(c.quote?.open_interest,0)}</b></div><div><small>VOLUME</small><b>${fmt(c.quote?.volume,0)}</b></div></div><div class="result-meta">Quote ${esc(when(c.quote?.quote_as_of))}<br>Last trade ${esc(when(c.quote?.last_trade_at))}</div></article>`).join('')||empty('Connect to discover HAL futures contracts and their lot sizes.');
 const prev=visit?.spot;if(snapshot&&C.finite(prev)&&C.finite(s.last_price))$('since-visit').innerHTML=dataRow('Spot change since '+when(visit.at),money(s.last_price-prev))+`<p class="small muted">Comparison with the previous saved visit. Position edits can change basket P&amp;L independently of market movement.</p>`;
}
function fillExpiries(){const current=snapshot?.option_expiry||'';$('expiry').innerHTML=(snapshot?.available_expiries||[]).map(d=>`<option value="${esc(d)}">${esc(dateText(d))}</option>`).join('')||'<option value="">Connect to load</option>';$('expiry').value=current;for(const id of ['roll-from','roll-to']){const old=$(id).value;$(id).innerHTML=(snapshot?.futures||[]).map(f=>`<option value="${esc(f.expiry)}">${esc(shortDate(f.expiry))}</option>`).join('');if([...$(id).options].some(o=>o.value===old))$(id).value=old;else $(id).selectedIndex=id==='roll-to'?Math.min(1,$(id).options.length-1):0;}}
function renderChain(){const filter=$('strike-filter').value,all=snapshot?.option_rows||[],spot=snapshot?.spot?.last_price;let closest=null;for(const r of all)if(C.finite(spot)&&(closest===null||Math.abs(r.strike-spot)<Math.abs(closest-spot)))closest=r.strike;const rows=filter?all.filter(r=>String(r.strike).startsWith(filter)):all;const head=chainMode==='greeks'?['Strike','IV %','Delta','Theta','Gamma','Vega']:['Strike','LTP','Bid','Ask','OI','IV %'];$('chain-head').innerHTML='<tr>'+head.map(h=>'<th scope="col">'+h+'</th>').join('')+'</tr>';$('chain-body').innerHTML=rows.map(r=>{const q=chainMode==='calls'?r.call:r.put,cols=chainMode==='greeks'?[r.strike,q?.iv,q?.delta,q?.theta,q?.gamma,q?.vega]:[r.strike,q?.ltp,q?.bid,q?.ask,q?.oi,q?.iv];return `<tr class="${book.legs.some(l=>l.type==='PE'&&l.strike===r.strike&&l.expiry===snapshot.option_expiry)?'focus-strike ':''}${r.strike===closest?'atm':''}">`+cols.map((v,i)=>'<td>'+fmt(v,chainMode==='greeks'&&i>1?4:2)+'</td>').join('')+'</tr>';}).join('')||'<tr><td colspan="6">'+esc(snapshot?.chain_error?issues[snapshot.chain_error]||'Chain unavailable':filter?'No matching strike':'No option data yet')+'</td></tr>';$('chain-summary').textContent=snapshot?rows.length+' strikes · '+dateText(snapshot.option_expiry)+' · Retrieved '+when(snapshot.fetched_at_iso):'Choose an expiry after connecting.';}
function formLeg(l,i){return `<article class="leg-card" data-index="${i}"><div class="leg-head"><h3>Leg ${i+1}</h3><button class="remove" data-remove="${i}" aria-label="Remove leg ${i+1}">×</button></div><div class="form-grid"><label>Long instrument<select data-field="type"><option value="FUT" ${l.type==='FUT'?'selected':''}>Futures</option><option value="PE" ${l.type==='PE'?'selected':''}>Protective put</option></select></label><label>Contract expiry<input data-field="expiry" type="date" value="${esc(l.expiry)}"></label><label>Number of lots<input data-field="lots" type="number" min="1" inputmode="numeric" value="${esc(l.lots)}"></label><label>Units per lot<input data-field="lotSize" type="number" min="1" inputmode="numeric" value="${esc(l.lotSize)}" placeholder="Verify contract"></label><label>Entry / premium (₹)<input data-field="entry" type="number" min="0" step="any" inputmode="decimal" value="${esc(l.entry)}"></label><label>Put strike (₹)<input data-field="strike" type="number" min="0" inputmode="decimal" ${l.type==='FUT'?'disabled':''} value="${esc(l.strike)}"></label><label>Manual mark · optional<input data-field="manual" type="number" min="0" inputmode="decimal" placeholder="Blank = Upstox" value="${esc(l.manual)}"></label></div></article>`;}
function renderForm(){$('position-form').innerHTML=draft.map(formLeg).join('')||empty('Your book is empty. Add a leg to begin.');}
function riskInsights(){const r=A.risk(book.legs,effectiveSnapshot()),items=r.warnings.map(w=>({...w,label:'Position structure',evidence:'Calculated from your saved contract expiries and units.'}));
 if(book.legs.length&&(!snapshot||lastFailed||C.freshness(snapshot)!=='Recent market quote'))items.unshift({level:'warn',label:'Data quality',title:'Review quote freshness',detail:'Price-dependent conclusions are paused. Your structural expiry and quantity checks remain available.',evidence:'Spot quote: '+when(snapshot?.spot?.quote_as_of)+'. Option-chain timestamps are not supplied.'});
 const t=technical('D');if(book.legs.length&&snapshot&&!lastFailed&&C.freshness(snapshot)==='Recent market quote'&&t.ready&&!t.stale&&r.futureUnits>0)items.push({level:t.bias==='Bearish'?'warn':'muted',label:'Technical context',title:t.bias+' daily structure',detail:t.bias==='Bearish'?'Daily price and momentum rules lean lower. Review your net long exposure and protection strikes.':t.bias==='Bullish'?'Daily price and momentum rules lean higher. Check that your hedge dates and premium budget still match your holding plan.':'The daily evidence is mixed. Compare price near support/resistance with your hedge coverage.',evidence:t.evidence.map(e=>e.label+': '+fmt(e.value)+' ('+e.reading+')').join('; ')+'. Completed bar: '+when(new Date(t.asOf).toISOString())});
 if(book.legs.length&&!items.length)items.push({label:'Position structure',title:'Your review starts here',detail:'Check your protection strikes, expiry timeline, liquidity and funding. Matching quantities alone do not guarantee full downside protection.',evidence:'Manual open book; not a broker statement.'});return {r,items};}
function insightCard(i){return `<article class="card insight ${i.level==='warn'?'warn':''}"><span class="insight-label">${esc(i.label||'Review')}</span><h3>${esc(i.title)}</h3><p>${esc(i.detail)}</p>${i.evidence?'<details><summary>View evidence</summary><p>'+esc(i.evidence)+'</p></details>':''}</article>`;}
function renderPositions(){const s=effectiveSnapshot(),result=C.mtm(book.legs,s),{r,items}=riskInsights();for(const id of ['basket-pnl','home-pnl']){$(id).textContent=money(result.total);color($(id),result.total);}const note=!book.legs.length?'Add your current futures and protective puts.':!result.complete?'Incomplete marks or contract mismatch. Basket P&L is unavailable.':(lastFailed?'Previous snapshot. ':'')+'Indicative '+(book.preferences.markMode==='bid'?'bid':'LTP')+' / manual marks. Before costs; check each leg’s timestamp.';$('pnl-note').textContent=note;$('home-pnl-note').textContent=note;$('home-units').textContent=fmt(r.futureUnits,0);$('home-coverage').textContent=C.finite(r.coverage)?fmt(r.coverage,0)+'%':'—';$('home-expiry').textContent=shortDate(r.nextExpiry);
 $('position-results').innerHTML=result.rows.map((l,i)=>`<article class="card"><div class="leg-result"><div class="leg-contract"><div class="contract-icon ${l.type==='PE'?'put':''}">${l.type}</div><div><strong>${l.type==='FUT'?'HAL futures':fmt(l.strike,0)+' put'}</strong><div class="small muted">${esc(shortDate(l.expiry))} · ${l.lots} × ${l.lotSize}</div></div></div><div><strong class="${C.finite(l.pnl)?l.pnl<0?'negative':'positive':''}">${money(l.pnl)}</strong><div class="small muted">${money(l.price)}</div></div></div><div class="result-meta">Entry ${money(l.entry)} · ${esc(l.source)}<br>${l.manual!==null?'Manual mark saved ':l.type==='PE'?'Contract quote ':'Quote '}${esc(when(l.stamp))}</div><button class="text-button record-close" data-close-leg="${i}">Record completed close ↗</button></article>`).join('')||empty('Your open book is empty. Add positions below.');
 $('home-insights').innerHTML=items.slice(0,3).map(insightCard).join('')||empty('Save your positions to see expiry, exposure and hedge insights.');$('risk-insights').innerHTML=items.map(insightCard).join('')||empty('Add positions to calculate your risk overview.');
 $('risk-metrics').innerHTML=tile('NET DELTA',fmt(r.delta,1),'Approximate share-equivalent units')+tile('THETA / DAY',money(r.theta),'Provider estimate; per day')+tile('PUT QUANTITY COVERAGE',C.finite(r.coverage)?fmt(r.coverage,1)+'%':'—','Put units ÷ active futures units')+tile('OPEN PUT ENTRY PREMIUM',money(r.premiumAtEntry),'Premium paid for open puts');
 $('expiry-timeline').innerHTML=r.timeline.map(t=>`<div class="timeline-row"><small>${esc(dateText(t.date))}</small><p>${t.expiring.map(l=>`${l.lots} × ${l.type==='FUT'?'futures':fmt(l.strike,0)+' put'}`).join(' · ')}</p>${t.futureUnits>0?`<p class="${t.uncovered?'gap':''}">After expiry: ${fmt(t.futureUnits,0)} futures units / ${fmt(t.putUnits,0)} put units${t.uncovered?' · '+fmt(t.uncovered,0)+' units without puts':''}</p>`:'<p>No later futures in the saved book.</p>'}</div>`).join('')||'<p class="small muted">No active expiry dates in your book.</p>';
 $('funding-note').textContent=book.funding.at?'Manual snapshot saved '+when(book.funding.at)+'. Free funds '+money(book.funding.free)+'; margin used '+money(book.funding.margin)+'. These are not strategy P&L.':'Funds and margin are separate from strategy P&L.';renderScenario();renderJournal();renderRollover();renderEvents();renderHedge();}
function renderScenario(){const spot=C.value($('scenario-price').value);try{const out=A.scenario(book.legs,effectiveSnapshot(),{spot,days:C.value($('scenario-days').value),ivShift:C.value($('scenario-iv').value),fallbackIV:C.value($('scenario-fallback').value),rate:C.value($('scenario-rate').value),dividend:C.value($('scenario-dividend').value)});$('scenario-pnl').textContent=money(out.total);color($('scenario-pnl'),out.total);$('scenario-note').textContent='Model horizon '+when(new Date(out.horizon).toISOString())+'. '+(lastFailed?'Uses a previous snapshot. ':'')+'Hypothetical value before costs, not a forecast. Source snapshot '+when(snapshot?.fetched_at_iso)+'.';$('scenario-rows').innerHTML=out.rows.map(l=>dataRow(l.type==='FUT'?'Futures '+shortDate(l.expiry):fmt(l.strike,0)+' put · IV '+fmt(l.iv,1)+'%',money(l.pnl))).join('');}catch(e){$('scenario-pnl').textContent='₹—';color($('scenario-pnl'),null);$('scenario-note').textContent=e.message;$('scenario-rows').innerHTML='';}try{const total=C.payoff(book.legs,spot);$('expiry-payoff').textContent=money(total);$('expiry-payoff-note').textContent='Settlement at '+money(spot)+' on '+dateText(book.legs[0].expiry)+', before costs.';}catch(e){$('expiry-payoff').textContent='₹—';$('expiry-payoff-note').textContent=e.message;}}
function renderRollover(){const a=snapshot?.futures?.find(f=>f.expiry===$('roll-from').value),b=snapshot?.futures?.find(f=>f.expiry===$('roll-to').value),valid=a&&b&&b.expiry>a.expiry&&a.quote?.last_price>0&&b.quote?.last_price>0;$('roll-spread').textContent=money(valid?b.quote.last_price-a.quote.last_price:null);$('roll-note').textContent=valid?'LTP comparison only. Quotes may be asynchronous; this is not an executable spread, realised expense or margin estimate. Current quote '+when(a.quote.quote_as_of)+'; later '+when(b.quote.quote_as_of)+'.':'Select two available contracts with a later destination expiry.';}
function renderJournal(){const j=A.ledger(book,effectiveSnapshot());$('journal-metrics').innerHTML=tile('REALISED P&L',money(j.realized),'Recorded completed closes')+tile('RECORDED CHARGES',money(j.charges),'Close charges + other costs')+tile('STRATEGY NET',money(j.net),'Realised + open P&L − costs')+tile('NET PUT PREMIUM',money(j.netPutPremium),'Open premiums + closed premiums net of sales');$('journal-list').innerHTML=[...book.journal].reverse().map(x=>{const gross=x.kind==='close'?(x.exit-x.leg.entry)*x.leg.lots*x.leg.lotSize:null;return `<article class="card journal-entry"><div class="title-row"><h3>${x.kind==='close'?x.leg.type+' completed close':x.kind==='fee'?'Cost recorded':'Settlement cash movement'}</h3><span class="small muted">${esc(shortDate(x.date))}</span></div>${x.kind==='close'?dataRow(x.leg.lots+' × '+x.leg.lotSize+' units · '+shortDate(x.leg.expiry),money(gross))+dataRow('Exit / fees',money(x.exit)+' / '+money(x.fees)):dataRow(x.kind==='fee'?'Cost':'Cash credit / debit',money(x.amount))}${x.note?'<p class="small muted">'+esc(x.note)+'</p>':''}<button class="text-button" data-edit-journal="${esc(x.id)}">Correct prices / amounts</button></article>`;}).join('')||empty('Record a completed close from a position card, or add a cost/cash entry.');$('history-list').innerHTML=dataRow('Recorded settlement cash (separate)',money(j.settlements))+history.slice(-6).reverse().map(h=>dataRow(when(h.at),money(h.net))).join('')+`<p class="fine">Snapshots are recorded while open, at most every 30 minutes. They are sparse observations, not continuous broker P&amp;L history.</p>`;}
function renderTechnical(){const t=technical();$('technical-summary').innerHTML=t.rows?.length?`<span class="eyebrow">${esc(frame==='D'?'DAILY':frame+' INTERVAL')} · RULE-BASED READING</span><h2 class="medium-value ${t.bias==='Bearish'?'negative':t.bias==='Bullish'?'positive':''}">${esc(t.bias)}</h2><p class="small muted">${t.rows.length} completed bars · Through ${esc(when(new Date(t.asOf).toISOString()))}${t.provisional?' · Incomplete latest bar excluded':''}</p><p class="fine">${esc(researchStatus('candles',frame))}</p>`:empty(researchStatus('candles',frame));$('technical-metrics').innerHTML=[['RSI 14',t.rsi,'Momentum'],['MACD',t.macd,'EMA 12 − EMA 26'],['ATR 14',t.atr,'Price volatility · ₹'],['MFI 14',t.mfi,'Price and volume'],['SMA 20',t.sma20,'Completed bars'],['SMA 50',t.sma50,'Completed bars'],['SMA 200',t.sma200,'Longer trend'],['REALIZED VOL',t.vol,frame==='D'?'20 returns · annualised %':'Daily-only measure']].map(([l,v,n])=>tile(l,fmt(v),n)).join('');$('technical-evidence').innerHTML=(t.evidence||[]).map(e=>dataRow(e.label+' · '+e.reading,fmt(e.value))).join('')+[['Pivot',t.pivot],['Pivot support S1',t.s1],['Pivot resistance R1',t.r1],['20-bar low',t.support],['20-bar high',t.resistance],['Bollinger lower',t.bbLow],['Bollinger upper',t.bbHigh]].map(([l,v])=>dataRow(l,fmt(v))).join('');$('technical-scenarios').innerHTML=t.ready&&!t.stale?[{label:'Bull scenario',title:'Strength beyond recent resistance',detail:'A completed close above '+money(t.resistance)+' would warrant reviewing breakout follow-through and volume. This condition has not necessarily occurred.'},{label:'Bear scenario',title:'Weakness below recent support',detail:'A completed close below '+money(t.support)+' would warrant reviewing downside exposure and put strikes. This is a condition to monitor.'},{label:'Neutral scenario',title:'Range and premium cost',detail:'While price remains within the recent range, compare put time decay with the protection you need. These are descriptive scenarios, not probabilities.'}].map(insightCard).join(''):empty('Directional scenarios wait for sufficient, recently fetched completed-bar data.');}
function historyTable(items,label){if(!items?.length)return '<p class="small muted">'+esc(label)+' unavailable.</p>';return '<div class="table-wrap"><table><thead><tr><th>Period</th><th>₹ crore</th><th>Period change</th></tr></thead><tbody>'+items.slice(0,8).map(h=>'<tr><td>'+esc(h.period)+'</td><td>'+fmt(h.value)+'</td><td>'+esc(h.change||'—')+'</td></tr>').join('')+'</tbody></table>';}
function renderFundamentals(){const packet=getResearch('fundamentals'),d=packet?.data||{},f=A.financialSummary(d);$('fundamental-status').textContent=researchStatus('fundamentals');$('fundamental-summary').innerHTML=f.revenue?`<span class="eyebrow">${esc(d.income?.type||'')} · QUARTERLY · ₹ CRORE</span><h2 class="medium-value">${esc(f.revenue.period)}</h2>${dataRow('Revenue',fmt(f.revenue.value))}${dataRow('Net profit',fmt(f.profit?.value))}${dataRow('Net margin',C.finite(f.margin)?fmt(f.margin)+'%':'Unavailable')}${dataRow('Operating margin',C.finite(f.opMargin)?fmt(f.opMargin)+'%':'Unavailable')}<p class="fine">Margins are calculated only from matching periods. Quarterly comparisons may be seasonal.</p>`:empty('Financial statements will appear when the provider returns them.');$('financials').innerHTML=(d.income?.income_statement||[]).map(r=>'<div class="card"><h3>'+esc(r.category.replaceAll('_',' '))+' · quarterly</h3>'+historyTable(r.history,r.category)+'</div>').join('')+(d.annual?.income_statement?.length?'<details class="card"><summary>Annual financial history</summary>'+d.annual.income_statement.map(r=>'<h3>'+esc(r.category.replaceAll('_',' '))+'</h3>'+historyTable(r.history,r.category)).join('')+'</details>':'');
 $('ratios').innerHTML=Array.isArray(d.ratios)?'<div class="table-wrap"><table><thead><tr><th>Ratio</th><th>HAL</th><th>Sector</th></tr></thead><tbody>'+d.ratios.map(r=>'<tr><td>'+esc(r.name)+'</td><td>'+esc(r.company_value)+'</td><td>'+esc(r.sector_value)+'</td></tr>').join('')+'</tbody></table><p class="fine">Provider ratios; reporting basis/date is not supplied by this endpoint. A sector comparison alone does not establish fair value.</p>':empty('Valuation ratios unavailable.');
 $('balance-cash').innerHTML=(d.cash?.cash_flow||[]).map(r=>'<details class="card"><summary>'+esc(r.category)+' cash flow · annual</summary>'+historyTable(r.history,r.category)+'</details>').join('')+'<div class="card">'+dataRow('Operating cash / matching annual profit',C.finite(f.conversion)?fmt(f.conversion)+'×':'Matching period unavailable')+'<p class="fine">Cash conversion uses matching annual periods and positive net profit.</p></div>'+(d.balance?.history?.length?'<div class="card"><h3>Assets &amp; liabilities · ₹ crore</h3>'+d.balance.history.slice(0,4).map(h=>dataRow(h.period,fmt(h.total_asset)+' / '+fmt(h.total_liability))).join('')+'<p class="fine">Total liabilities are not the same as debt.</p></div>':'')+(['balance','cash','annual'].map(k=>d[k]?.full_statement?.length?'<details class="card"><summary>'+esc(k)+' · detailed annual statement</summary>'+d[k].full_statement.map(row=>dataRow(row.particular,fmt(row.history?.[0]?.value)+' · '+(row.history?.[0]?.period||''))).join('')+'</details>':'').join(''));
 $('shareholding').innerHTML=Array.isArray(d.shareholding)?d.shareholding.map(r=>dataRow(r.category.replaceAll('_',' '),fmt(r.history?.[0]?.value)+'% · '+(r.history?.[0]?.period||'—'))).join('')+'<p class="fine">Provider categories shown separately; mutual funds are not added twice to institutional holdings.</p>':empty('Shareholding data unavailable.');
 $('peer-context').innerHTML=(d.profile?.sector?dataRow('Sector',d.profile.sector):'')+(d.profile?.company_profile?'<p class="small muted">'+esc(d.profile.company_profile)+'</p>':'')+(Array.isArray(d.peers)?'<details><summary>Provider peer universe</summary>'+d.peers.slice(0,12).map(p=>dataRow(p.name||p.company_name||p.trading_symbol||p.isin||p.instrument_key,p.sector||'—')).join('')+'<p class="fine">Peer profiles are context, not a like-for-like valuation ranking.</p></details>':'')||empty('Company profile and peer context unavailable.');renderEvents();}
function combineNews(){const news=A.newsItems(getResearch('news')?.data?.articles),filings=(getResearch('filings')?.data?.items||[]).filter(n=>A.safeURL(n.url)).map(n=>({...n,title:String(n.title||''),summary:String(n.summary||''),url:A.safeURL(n.url),official:true,topic:A.topic(n.title+' '+n.summary)}));allNews=[...news,...filings].sort((a,b)=>(Date.parse(b.published)||0)-(Date.parse(a.published)||0));return {news,filings};}
function newsCard(group,compact=false){const n=group.item,saved=book.bookmarks.some(b=>b.url===n.url);return `<article class="card news-card"><div class="news-meta"><span class="news-source">${esc(n.official?'NSE disclosure':n.source||'Saved source')}</span><span>${esc(when(n.published))}</span></div><h3>${esc(n.title)}</h3>${HALNewsAI.decorate(n)}${!compact&&n.summary?'<p>'+esc(n.summary)+'</p>':''}${!compact?'<span class="news-topic">'+esc(n.topic||'Saved')+'</span>':''}${!compact?'<p class="fine">'+(n.official?'Exchange-filed disclosure. Open the attachment to assess details.':'Media report. No matching company disclosure has been established automatically.')+'</p>':''}${group.related.length?'<details><summary>'+group.related.length+' similar headline(s)</summary>'+group.related.map(r=>'<button class="text-button source-link" data-url="'+esc(r.url)+'">'+esc(r.title)+' ↗</button>').join('')+'</details>':''}<div class="news-actions"><button class="text-button source-link" data-url="${esc(n.url)}">Read source ↗</button><button class="text-button" data-bookmark="${esc(n.url)}">${saved?'Saved ✓':'Save +'}</button></div></article>`;}
function renderNews(){const {news,filings}=combineNews();HALNewsAI.maybeScore(allNews);let items=allNews;if(newsFilter==='saved')items=book.bookmarks.map(n=>({...n,summary:'Saved link. Open the original source for the full article.'}));else if(newsFilter==='official')items=filings;else if(newsFilter!=='all')items=allNews.filter(n=>n.topic===newsFilter);const groups=A.groupNews(items);$('news-list').innerHTML=groups.map(g=>newsCard(g)).join('')||empty(newsFilter==='saved'?'Save articles to build your reading list.':'No matching items in the available feeds. This does not establish that no news exists.');$('news-status').textContent=researchStatus('news')+' · News API covers the last 7 days. '+researchStatus('filings');$('home-news').innerHTML=A.groupNews(allNews).slice(0,2).map(g=>newsCard(g,true)).join('')||empty('News and official disclosures appear here after connecting.');$('filings').innerHTML=A.groupNews(filings).slice(0,15).map(g=>newsCard(g)).join('')||empty('No HAL items in the current RSS window. Open NSE or HAL investor relations to check the full filing history.');$('filing-status').textContent=researchStatus('filings');}
function renderEvents(){const actions=getResearch('fundamentals')?.data?.actions||[],events=[];for(const l of book.legs)if(A.daysLeft(l.expiry)>=0)events.push({date:l.expiry,title:(l.type==='FUT'?'Futures':fmt(l.strike,0)+' put')+' expiry',source:'Saved position'});for(const a of actions){const time=Date.parse(a.expiry_date);if(Number.isFinite(time)&&time>=Date.now()-86400000)events.push({date:A.istDate(time),title:a.name+(C.finite(a.amount)?' · '+money(a.amount):''),source:'Upstox corporate action'});}for(const n of book.notes)if(n.eventDate&&n.eventDate>=A.istDate())events.push({date:n.eventDate,title:n.title,source:'Your dated note'});events.sort((a,b)=>a.date.localeCompare(b.date));$('home-events').innerHTML=events.slice(0,6).map(e=>dataRow(shortDate(e.date),e.title+' · '+e.source)).join('')||'<p class="small muted">No upcoming dates in the available data. Results dates can be recorded with a sourced business note.</p>';}
function renderNotes(){$('business-notes').innerHTML=[...book.notes].reverse().map(n=>`<article class="card"><div class="news-meta"><span>${esc(n.category)} · YOUR NOTE</span><span>${esc(shortDate(n.date))}</span></div><h3>${esc(n.title)}</h3><p class="small muted">${esc(n.text)}</p>${n.eventDate?dataRow('Recorded event date',dateText(n.eventDate)):''}<div class="news-actions">${n.url?'<button class="text-button source-link" data-url="'+esc(n.url)+'">Open source ↗</button>':'<span class="fine">No source link recorded</span>'}<button class="text-button delete-note" data-delete-note="${esc(n.id)}">Delete</button></div></article>`).join('');}
function renderHealth(){$('data-health').innerHTML=dataRow('Market snapshot',snapshot?when(snapshot.fetched_at_iso):'Not loaded')+['candles','news','fundamentals','filings','status','context'].map(s=>'<div class="health-item"><b>'+esc(s)+'</b><span>'+esc(researchStatus(s,s==='candles'?frame:'D'))+'</span></div>').join('');}
function renderMarketPulse(){if(window.HALMarketPulse){HALMarketPulse.renderInto('pulse-home',getResearch('context'),researchStatus('context'));HALMarketPulse.renderInto('pulse-markets',getResearch('context'),researchStatus('context'));}}
function renderAll(){renderMarketPulse();renderMarket();renderChain();renderPositions();renderTechnical();renderFundamentals();renderNews();renderNotes();renderHealth();renderCharts();renderIntelligence();renderDesk();}
function action(title,html,label,save){$('action-title').textContent=title;$('action-body').innerHTML=html;$('action-save').textContent=label;$('action-error').textContent='';actionSave=save;$('action-dialog').showModal();}
function closePosition(index){const leg=book.legs[index];if(!leg)return;action('Record a completed close',`<p class="small muted">Record a trade or settlement already completed with your broker. This updates your local book only.</p><div class="form-grid"><label>Lots closed<input id="close-lots" type="number" value="${leg.lots}" min="1" max="${leg.lots}"></label><label>Actual exit price (₹)<input id="close-price" type="number" min="0" inputmode="decimal"></label><label>Total charges (₹)<input id="close-fees" type="number" value="0" min="0" inputmode="decimal"></label><label>Close date<input id="close-date" type="date" value="${A.istDate()}"></label></div>`, 'Record close',()=>{saveBook(A.closeLeg(book,index,C.value($('close-lots').value),C.value($('close-price').value),C.value($('close-fees').value),$('close-date').value));draft=book.legs.map(l=>({...l,manual:l.manual??''}));renderForm();renderAll();toast('Completed close recorded; open quantity updated.');});}
function cashEntry(){action('Record cash or cost',`<p class="small muted">Add costs once. Futures settlement cash is tracked separately and is not added to P&amp;L again.</p><label>Entry type<select id="cash-kind"><option value="fee">Additional charges / funding cost</option><option value="settlement">Futures settlement cash</option></select></label><div class="form-grid"><label>Amount (₹)<input id="cash-amount" type="number" inputmode="decimal" placeholder="Credit + / debit −"></label><label>Date<input id="cash-date" type="date" value="${A.istDate()}"></label></div><label>Note<textarea id="cash-note" maxlength="1000" placeholder="Source or broker statement reference"></textarea></label>`,'Save entry',()=>{const kind=$('cash-kind').value,amount=C.value($('cash-amount').value),date=$('cash-date').value;if(!C.finite(amount)||(kind==='fee'&&amount<0)||!C.validDate(date)||date>A.istDate())throw Error('Enter a valid amount and past/current date. Costs must be non-negative.');saveBook({...book,journal:[...book.journal,{id:'j-'+Date.now(),kind,amount,date,note:$('cash-note').value}]});renderJournal();renderDesk();toast('Journal entry saved.');});}
function editJournal(id){const j=book.journal.find(x=>x.id===id);if(!j)return;action('Correct journal entry',`<p class="small muted">This corrects recorded values. Closed quantities and your open book stay as recorded.</p>${j.kind==='close'?'<div class="form-grid"><label>Actual exit price<input id="edit-exit" type="number" value="'+j.exit+'"></label><label>Charges<input id="edit-fees" type="number" value="'+j.fees+'"></label></div>':'<label>Amount<input id="edit-amount" type="number" value="'+j.amount+'"></label>'}<label>Note<textarea id="edit-note" maxlength="1000">${esc(j.note||'')}</textarea></label>`,'Save correction',()=>{const next={...j,note:$('edit-note').value};if(j.kind==='close'){next.exit=C.value($('edit-exit').value);next.fees=C.value($('edit-fees').value);}else next.amount=C.value($('edit-amount').value);saveBook({...book,journal:book.journal.map(x=>x.id===id?next:x)});renderJournal();renderDesk();});}
function addNote(){action('Add a sourced business note',`<label>Topic<select id="note-category"><option>Order book</option><option>Deliveries</option><option>Guidance</option><option>Results</option><option>Other</option></select></label><label>Title<input id="note-title" maxlength="200" placeholder="What changed?"></label><label>Reported facts and your interpretation<textarea id="note-text" maxlength="3000" placeholder="Include period, units and what remains uncertain."></textarea></label><label>Original source (HTTPS)<input id="note-url" type="url" placeholder="https://…"></label><label>Upcoming event date · optional<input id="note-event" type="date"></label>`,'Save note',()=>{const title=$('note-title').value.trim(),text=$('note-text').value.trim(),url=$('note-url').value.trim(),eventDate=$('note-event').value;if(!title||!text)throw Error('Add a title and note.');if(url&&!A.safeURL(url))throw Error('Use a valid public HTTPS source link.');if(eventDate&&!C.validDate(eventDate))throw Error('Check the event date.');saveBook({...book,notes:[...book.notes,{id:'n-'+Date.now(),date:A.istDate(),category:$('note-category').value,title,text,url,eventDate:eventDate||null}]});renderNotes();renderEvents();});}
function exportCSV(){const cell=x=>'"'+(typeof x==='number'?String(x):String(x??'').replace(/^[\s]*[=+@-]/,"'$&")).replaceAll('"','""')+'"';const rows=[['Date','Kind','Contract','Expiry','Lots','Units per lot','Entry','Exit','Gross P&L','Charges','Cash amount','Note'],...book.journal.map(j=>[j.date,j.kind,j.leg?.type,j.leg?.expiry,j.leg?.lots,j.leg?.lotSize,j.leg?.entry,j.exit,j.kind==='close'?(j.exit-j.leg.entry)*j.leg.lots*j.leg.lotSize:'',j.kind==='close'?j.fees:j.kind==='fee'?j.amount:'',j.kind==='settlement'?j.amount:'',j.note])];native('exportCSV','\uFEFF'+rows.map(r=>r.map(cell).join(',')).join('\r\n'));}
function importPreview(data){try{let b=data.book||data;if(b.version===1)b={...A.emptyBook(),legs:b.legs};const imported=A.validateBook(b),hist=Array.isArray(data.history)?data.history.filter(h=>h&&Number.isFinite(Date.parse(h.at))&&(h.net===null||C.finite(h.net))&&(h.spot===null||C.finite(h.spot))).slice(-5000).map(h=>({at:h.at,net:h.net,spot:h.spot})):[];action('Review backup import',`<p>This backup contains <b>${imported.legs.length} open legs</b>, <b>${imported.journal.length} journal entries</b>, ${imported.notes.length} notes and ${imported.bookmarks.length} bookmarks.</p><p class="small muted">Import replaces the current local book. A recovery copy of the current book is retained on this phone. Tokens are never imported.</p>`,'Replace with this backup',()=>{localStorage.setItem('hal_before_import_v2',JSON.stringify(book));saveBook(imported);history=hist;draft=book.legs.map(l=>({...l,manual:l.manual??''}));syncSettings();applyTheme();renderForm();renderAll();saveCache();toast('Backup imported.');});}catch(e){toast('Backup rejected: '+e.message);}}
function syncSettings(){syncHedgeForm();syncDeskProfile();$('theme').value=book.preferences.theme;$('auto').checked=book.preferences.auto;$('mark-mode').value=book.preferences.markMode;$('funding-margin').value=book.funding.margin??'';$('funding-free').value=book.funding.free??'';}
function receive(event,data){
 if(HALNewsAI.receive(event,data))return;
 if(receiveAI(event,data))return;
 if(event==='connection'){mode=data.mode;configured=!!data.configured;$('connection-label').textContent=configured?(mode==='server'?'Upstox via Render':'Upstox · Analytics-first'):'Connect your data';$('connection-type').textContent=mode==='server'?'Render server · viewer key':'Direct Upstox · encrypted token';if(!started){started=true;if(configured)refresh();}}
 if(event==='loading'){loading=true;$('refresh').disabled=true;$('expiry').disabled=true;notice('Refreshing HAL market data…','busy');renderDesk();}
 if(event==='idle'){loading=false;$('refresh').disabled=false;$('expiry').disabled=false;renderDesk();}
 if(event==='snapshot'){if(!data?.spot||!Array.isArray(data.futures)){receive('error',{code:'bad_response'});return;}const firstSnapshot=!snapshot;snapshot={...data,chains:{...(snapshot?.chains||{}),[data.option_expiry]:{option_expiry:data.option_expiry,option_rows:data.option_rows,fetched_at_iso:data.fetched_at_iso,chain_error:data.chain_error}}};lastFailed=false;loading=false;$('refresh').disabled=false;$('expiry').disabled=false;$('connection-dot').className='connected';notice(data.chain_error?'Quotes updated; option chain unavailable.':C.freshness(data)!=='Recent market quote'?'Quote timestamp: '+when(data.spot.quote_as_of)+'. '+C.freshness(data)+'.':'',data.chain_error?'error':'');fillExpiries();if(!$('scenario-price').value)$('scenario-price').value=data.spot.last_price;const net=A.ledger(book,effectiveSnapshot()).net;if(!history.length||Date.now()-Date.parse(history.at(-1).at)>=1800000)history.push({at:data.fetched_at_iso,spot:data.spot.last_price,net:book.legs.length||book.journal.length?net:null});try{localStorage.setItem('hal_last_visit_v2',JSON.stringify({at:data.fetched_at_iso,spot:data.spot.last_price}));}catch(e){}saveCache();renderAll();if(firstSnapshot&&tab==='overview')window.scrollTo(0,0);primeResearch();}
 if(event==='error'){loading=false;lastFailed=true;$('refresh').disabled=false;$('expiry').disabled=false;$('connection-dot').className='';notice((issues[data.code]||'Market data unavailable.')+(snapshot?' Showing the previous snapshot.':''),'error');renderMarket();renderPositions();renderIntelligence();renderDesk();}
 if(event==='research'){const k=data.key||key(data.section,data.frame);pending.delete(k);failed.delete(k);if(data.section==='chain'){if(snapshot&&data.data?.option_expiry){snapshot.chains={...(snapshot.chains||{}),[data.data.option_expiry]:data.data};}research[k]={...data,data:{}};}else research[k]=data;saveCache();renderAll();}
 if(event==='research_error'){pending.delete(data.key);failed.set(data.key,data.code);renderPositions();renderTechnical();renderFundamentals();renderNews();renderHealth();renderMarketPulse();renderIntelligence();renderDesk();}
 if(event==='reset'){$('since-visit').textContent='Your first snapshot establishes a comparison point.';snapshot=null;research={};pending.clear();failed.clear();researchStarted.clear();lastFailed=false;loading=false;$('refresh').disabled=false;$('expiry').disabled=false;fillExpiries();saveCache();renderAll();notice(configured?'Connection saved. Refreshing…':'Credentials removed. Your local book is preserved.');}
 if(event==='file_saved')toast('File saved.');if(event==='file_error')toast(data.message||'File operation failed.');if(event==='import_preview')importPreview(data);
}
window.HALApp={receive,back:()=>{if($('action-dialog').open)$('action-dialog').close();else if($('settings-dialog').open)$('settings-dialog').close();else if($('market-chart-card').classList.contains('expanded')){$('market-chart-card').classList.remove('expanded');renderCharts();}else if(tab!=='overview')switchTab('overview');else native('minimize');}};
